import json, collections
data = json.loads(open('graphify-out/graph.json', encoding='utf-8').read())
nodes = {n['id']: n for n in data['nodes']}
links = data['links']

indeg = collections.Counter()
for l in links:
    if l.get('relation') in ('calls','indirect_call'):
        indeg[l['target']] += 1

# filter targets whose source_file is under internal/
ranked = []
for tid, cnt in indeg.items():
    n = nodes.get(tid, {})
    src = n.get('source_file') or n.get('src') or ''
    if src.startswith('internal/'):
        ranked.append((cnt, tid, src, n.get('label') or n.get('name')))

ranked.sort(reverse=True)
for r in ranked[:20]:
    print(r)
"

